1	<?php
2	
3	require(__DIR__ . '/includes/session.php');
4	
5	$Title = __('Payment Terms Maintenance');
6	$ViewTopic = 'PaymentTerms';
7	$BookMark = 'PaymentTerms';
8	include('includes/header.php');
9	
10	echo '<p class="page_title_text">
11			<img src="'.$RootPath.'/css/'.$Theme.'/images/money_add.png" title="' . __('Payment Terms') . '" alt="" />' . ' ' . $Title .
12		'</p>';
13	
14	if (isset($_GET['SelectedTerms'])){
15		$SelectedTerms = $_GET['SelectedTerms'];
16	} elseif (isset($_POST['SelectedTerms'])){
17		$SelectedTerms = $_POST['SelectedTerms'];
18	}
19	
20	$Errors = array();
21	
22	if (isset($_POST['submit'])) {
23	
24		//initialise no input errors assumed initially before we test
25		$InputError = 0;
26	
27		/* actions to take once the user has clicked the submit button
28		ie the page has called itself with some user input */
29		$i=1;
30	
31		//first off validate inputs are sensible
32	
33		if (mb_strlen($_POST['TermsIndicator']) < 1) {
34			$InputError = 1;
35			prnMsg(__('The payment terms name must exist'),'error');
36			$Errors[$i] = 'TermsIndicator';
37			$i++;
38		}
39		if (mb_strlen($_POST['TermsIndicator']) > 2) {
40			$InputError = 1;
41			prnMsg(__('The payment terms name must be two characters or less long'),'error');
42			$Errors[$i] = 'TermsIndicator';
43			$i++;
44		}
45		if (empty($_POST['DayNumber']) OR !is_numeric(filter_number_format($_POST['DayNumber'])) OR filter_number_format($_POST['DayNumber']) <= 0){
46			$InputError = 1;
47			prnMsg( __('The number of days or the day in the following month must be numeric') ,'error');
48			$Errors[$i] = 'DayNumber';
49			$i++;
50		}
51		if (empty($_POST['Terms']) OR mb_strlen($_POST['Terms']) > 40) {
52			$InputError = 1;
53			prnMsg( __('The terms description must be forty characters or less long') ,'error');
54			$Errors[$i] = 'Terms';
55			$i++;
56		}
57		/*
58		if ($_POST['DayNumber'] > 30 AND empty($_POST['DaysOrFoll'])) {
59			$InputError = 1;
60			prnMsg( __('When the check box is not checked to indicate a day in the following month is the due date') . ', ' . __('the due date cannot be a day after the 30th') . '. ' . __('A number between 1 and 30 is expected') ,'error');
61			$Errors[$i] = 'DayNumber';
62			$i++;
63		} */
64		if ($_POST['DayNumber']>360 AND !empty($_POST['DaysOrFoll'])) {
65			$InputError = 1;
66			prnMsg( __('When the check box is checked to indicate that the term expects a number of days after which accounts are due') . ', ' . __('the number entered should be less than 361 days') ,'error');
67			$Errors[$i] = 'DayNumber';
68			$i++;
69		}
70	
71		if (isset($SelectedTerms) AND $InputError != 1) {
72	
73			/*SelectedTerms could also exist if submit had not been clicked this code would not run in this case cos submit is false of course  see the delete code below*/
74	
75			if (isset($_POST['DaysOrFoll']) AND $_POST['DaysOrFoll']=='on') {
76				$SQL = "UPDATE paymentterms SET
77								terms='" . $_POST['Terms'] . "',
78								dayinfollowingmonth=0,
79								daysbeforedue='" . filter_number_format($_POST['DayNumber']) . "'
80						WHERE termsindicator = '" . $SelectedTerms . "'";
81			} else {
82				$SQL = "UPDATE paymentterms SET
83								terms='" . $_POST['Terms'] . "',
84								dayinfollowingmonth='" . filter_number_format($_POST['DayNumber']) . "',
85								daysbeforedue=0
86							WHERE termsindicator = '" . $SelectedTerms . "'";
87			}
88	
89			$Msg = __('The payment terms definition record has been updated') . '.';
90		} elseif ($InputError != 1) {
91	
92		/*Selected terms is null cos no item selected on first time round so must be adding a record must be submitting new entries in the new payment terms form */
93	
94			if ($_POST['DaysOrFoll']=='on') {
95				$SQL = "INSERT INTO paymentterms (termsindicator,
96									terms,
97									daysbeforedue,
98									dayinfollowingmonth)
99							VALUES (
100								'" . $_POST['TermsIndicator'] . "',
101								'" . $_POST['Terms'] . "',
102								'" . filter_number_format($_POST['DayNumber']) . "',
103								0
104							)";
105			} else {
106				$SQL = "INSERT INTO paymentterms (termsindicator,
107									terms,
108									daysbeforedue,
109									dayinfollowingmonth)
110							VALUES (
111								'" . $_POST['TermsIndicator'] . "',
112								'" . $_POST['Terms'] . "',
113								0,
114								'" . filter_number_format($_POST['DayNumber']) . "'
115								)";
116			}
117	
118			$Msg = __('The payment terms definition record has been added') . '.';
119		}
120		if ($InputError != 1){
121			//run the SQL from either of the above possibilites
122			$Result = DB_query($SQL);
123			prnMsg($Msg,'success');
124			unset($SelectedTerms);
125			unset($_POST['DaysOrFoll']);
126			unset($_POST['TermsIndicator']);
127			unset($_POST['Terms']);
128			unset($_POST['DayNumber']);
129		}
130	
131	} elseif (isset($_GET['delete'])) {
132	//the link to delete a selected record was clicked instead of the submit button
133	
134	// PREVENT DELETES IF DEPENDENT RECORDS IN DebtorsMaster
135	
136		$SQL= "SELECT COUNT(*) FROM debtorsmaster WHERE debtorsmaster.paymentterms = '" . $SelectedTerms . "'";
137		$Result = DB_query($SQL);
138		$MyRow = DB_fetch_row($Result);
139		if ($MyRow[0] > 0) {
140			prnMsg( __('Cannot delete this payment term because customer accounts have been created referring to this term'),'warn');
141			echo '<br /> ' . __('There are') . ' ' . $MyRow[0] . ' ' . __('customer accounts that refer to this payment term');
142		} else {
143			$SQL= "SELECT COUNT(*) FROM suppliers WHERE suppliers.paymentterms = '" . $SelectedTerms . "'";
144			$Result = DB_query($SQL);
145			$MyRow = DB_fetch_row($Result);
146			if ($MyRow[0] > 0) {
147				prnMsg( __('Cannot delete this payment term because supplier accounts have been created referring to this term'),'warn');
148				echo '<br /> ' . __('There are') . ' ' . $MyRow[0] . ' ' . __('supplier accounts that refer to this payment term');
149			} else {
150				//only delete if used in neither customer or supplier accounts
151	
152				$SQL="DELETE FROM paymentterms WHERE termsindicator='" . $SelectedTerms . "'";
153				$Result = DB_query($SQL);
154				prnMsg( __('The payment term definition record has been deleted') . '!','success');
155			}
156		}
157		//end if payment terms used in customer or supplier accounts
158	
159	}
160	
161	if (!isset($SelectedTerms)) {
162	
163	/* It could still be the second time the page has been run and a record has been selected for modification - SelectedTerms will exist because it was sent with the new call. If its the first time the page has been displayed with no parameters
164	then none of the above are true and the list of payment termss will be displayed with
165	links to delete or edit each. These will call the same page again and allow update/input
166	or deletion of the records*/
167	
168		$SQL = "SELECT termsindicator, terms, daysbeforedue, dayinfollowingmonth FROM paymentterms";
169		$Result = DB_query($SQL);
170	
171		echo '<table class="selection">';
172		echo '<thead>
173				<tr>
174					<th colspan="6"><h3>' . __('Payment Terms.') . '</h3></th>
175				</tr>';
176		echo '<tr>
177				<th class="SortedColumn">' . __('Term Code') . '</th>
178				<th class="SortedColumn">' . __('Description') . '</th>
179				<th class="SortedColumn">' . __('Following Month On') . '</th>
180				<th class="SortedColumn">' . __('Due After (Days)') . '</th>
181			</tr>
182		</thead>';
183	
184		while ($MyRow=DB_fetch_array($Result)) {
185	
186			if ($MyRow['dayinfollowingmonth']==0) {
187				$FollMthText = __('N/A');
188			} else {
189				$FollMthText = $MyRow['dayinfollowingmonth'] . __('th');
190			}
191	
192			if ($MyRow['daysbeforedue']==0) {
193				$DueAfterText = __('N/A');
194			} else {
195				$DueAfterText = $MyRow['daysbeforedue'] . ' ' . __('days');
196			}
197	
198		echo '<tr class="striped_row">
199				<td>', $MyRow['termsindicator'], '</td>
200				<td>', $MyRow['terms'], '</td>
201				<td>', $FollMthText, '</td>
202				<td>', $DueAfterText, '</td>
203				<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '?SelectedTerms=', $MyRow[0], '">' . __('Edit') . '</a></td>
204				<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '?SelectedTerms=', $MyRow[0], '&amp;delete=1" onclick="return confirm(\'' . __('Are you sure you wish to delete this payment term?') . '\');">' . __('Delete') . '</a></td>
205			</tr>';
206	
207		} //END WHILE LIST LOOP
208		echo '</table>';
209	} //end of ifs and buts!
210	
211	if (isset($SelectedTerms)) {
212		echo '<div class="centre">
213				<a href="' . htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8') . '">' . __('Show all Payment Terms Definitions') . '</a>
214			</div>';
215	}
216	
217	if (!isset($_GET['delete'])) {
218	
219		echo '<form method="post" action="' . htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8') . '">';
220		echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
221	
222		if (isset($SelectedTerms)) {
223			//editing an existing payment terms
224	
225			$SQL = "SELECT termsindicator,
226							terms,
227							daysbeforedue,
228							dayinfollowingmonth
229						FROM paymentterms
230						WHERE termsindicator='" . $SelectedTerms . "'";
231	
232			$Result = DB_query($SQL);
233			$MyRow = DB_fetch_array($Result);
234	
235			$_POST['TermsIndicator'] = $MyRow['termsindicator'];
236			$_POST['Terms']  = $MyRow['terms'];
237			$DaysBeforeDue  = $MyRow['daysbeforedue'];
238			$DayInFollowingMonth  = $MyRow['dayinfollowingmonth'];
239	
240			echo '<input type="hidden" name="SelectedTerms" value="' . $SelectedTerms . '" />';
241			echo '<input type="hidden" name="TermsIndicator" value="' . $_POST['TermsIndicator'] . '" />';
242			echo '<fieldset>';
243			echo '<legend>' . __('Update Payment Terms.') . '</legend>';
244			echo '<field>
245					<label for="TermsIndicator">' . __('Term Code') . ':</label>
246					<fieldtext>' . $_POST['TermsIndicator'] . '</fieldtext>
247				</field>';
248	
249		} else { //end of if $SelectedTerms only do the else when a new record is being entered
250	
251			if (!isset($_POST['TermsIndicator'])) $_POST['TermsIndicator']='';
252			if (!isset($DaysBeforeDue)) {
253				$DaysBeforeDue=0;
254			}
255			//if (!isset($DayInFollowingMonth)) $DayInFollowingMonth=0;
256			unset($DayInFollowingMonth); // Rather unset for a new record
257			if (!isset($_POST['Terms'])) {
258				$_POST['Terms']='';
259			}
260	
261			echo '<fieldset>';
262			echo '<legend>' . __('New Payment Terms.') . '</legend>';
263			echo '<field>
264					<label for="TermsIndicator">' . __('Term Code') . ':</label>
265					<input type="text" name="TermsIndicator"' . (in_array('TermsIndicator',$Errors) ? 'class="inputerror"' : '' ) .' autofocus="autofocus" required="required" pattern="[0-9a-ZA-Z_]*" title="" value="' . $_POST['TermsIndicator'] . '" size="3" maxlength="2" />
266					<fieldhelp>' . __('A 2 character code to identify this payment term. Any alpha-numeric characters can be used') . '</fieldhelp>
267				</field>';
268		}
269	
270		echo '<field>
271				<label for="Terms">' .  __('Terms Description'). ':</label>
272				<input type="text"' . (in_array('Terms',$Errors) ? 'class="inputerror"' : '' ) .' name="Terms" ' . (isset($SelectedTerms)? 'autofocus="autofocus"': '') . ' required="required" value="'.$_POST['Terms']. '" title="" size="35" maxlength="40" />
273				<fieldhelp>' . __('A description of the payment terms is required') . '</fieldhelp>
274			</field>';
275	
276		echo '<field>
277				<label for="DaysOrFoll">' . __('Due After A Given No. Of Days').':</label>
278				<input type="checkbox" name="DaysOrFoll" ';
279		if (isset($DayInFollowingMonth) AND !$DayInFollowingMonth) {
280			echo 'checked';
281		}
282		echo ' /></td>
283			</field>';
284	
285		echo '<field>
286				<label for="DayNumber">' . __('Days (Or Day In Following Month)').':</label>
287				<input type="text" ' . (in_array('DayNumber',$Errors) ? 'class="inputerror"' : '' ) .' name="DayNumber" required="required" class="integer"  size="4" maxlength="3" value="';
288		if ($DaysBeforeDue != 0) {
289			echo locale_number_format($DaysBeforeDue,0);
290		} else {
291			if (isset($DayInFollowingMonth)) {
292				echo locale_number_format($DayInFollowingMonth,0);
293			}
294		}
295		echo '" />
296			<field>
297		</fieldset>';
298	
299		echo '<div class="centre">
300				<input type="submit" name="submit" value="'.__('Enter Information').'" />
301			</div>';
302		echo '</form>';
303	} //end if record deleted no point displaying form to add record
304	
305	include('includes/footer.php');
306

