content.content:
150			/*Get suggested FunctionalExRate between the bank account currency and the home (functional) currency */
151			$Result = DB_query("SELECT rate, decimalplaces FROM currencies WHERE currabrev='" . $_SESSION['ReceiptBatch' . $identifier]->AccountCurrency . "'");
152			$MyRow = DB_fetch_array($Result);
153			$SuggestedFunctionalExRate = $MyRow['rate'];
154			$_SESSION['ReceiptBatch' . $identifier]->CurrDecimalPlaces = $MyRow['decimalplaces'];
155	
156		} //end else account currency !=  functional currency
157	
158		if ($_POST['Currency']==$_SESSION['ReceiptBatch' . $identifier]->AccountCurrency){
159			$_SESSION['ReceiptBatch' . $identifier]->ExRate = 1; //ex rate between receipt currency and account currency
160			$SuggestedExRate=1;
161		} elseif (isset($_POST['Currency'])) {
162			/*Get the exchange rate between the functional currency and the receipt currency*/
163			$Result = DB_query("SELECT rate FROM currencies WHERE currabrev='" . $_SESSION['ReceiptBatch' . $identifier]->Currency . "'");
164			$MyRow = DB_fetch_array($Result);
165			$TableExRate = $MyRow['rate']; //this is the rate of exchange between the functional currency and the receipt currency
166			/*Calculate cross rate to suggest appropriate exchange rate between receipt currency and account currency */
167			$SuggestedExRate = $TableExRate/$SuggestedFunctionalExRate;
168		}
169	
170		$_SESSION['ReceiptBatch' . $identifier]->BankTransRef = $_POST['BankTransRef'];
171		$_SESSION['ReceiptBatch' . $identifier]->Narrative = $_POST['BatchNarrative'];
172	
173	} elseif (isset($_GET['Delete'])) {
174		/* User hit delete the receipt entry from the batch */
175		$_SESSION['ReceiptBatch' . $identifier]->remove_receipt_item($_GET['Delete']);
176	} else { //it must be a new receipt batch
177		$_SESSION['ReceiptBatch' . $identifier] = new Receipt_Batch;
178	}
179	
180	
181	if (isset($_POST['Process'])){ //user hit submit a new entry to the receipt batch
182	
183		if (!isset($_POST['GLCode'])) {
184			$_POST['GLCode']='';
185		}
186		if (!isset($_POST['tag'])) {
187			$_POST['tag']='';
188		}
189		if (!isset($_POST['CustomerID'])) {
190			$_POST['CustomerID']='';
191		}
192		if (!isset($_POST['CustomerName'])) {
193			$_POST['CustomerName']='';
194		}
195		if ($_POST['Discount']==0 AND $ReceiptTypes[$_SESSION['ReceiptBatch' . $identifier]->ReceiptType]['percentdiscount']>0){
196			if (isset($_GET['Type']) AND $_GET['Type'] == 'Customer') {
197				$_POST['Discount'] = $_POST['Amount']*$ReceiptTypes[$_SESSION['ReceiptBatch' . $identifier]->ReceiptType]['percentdiscount'];
198			}
199		}
200	
201		if ($_POST['GLCode'] == '' AND $_GET['Type']=='GL') {
202			prnMsg( __('No General Ledger code has been chosen') . ' - ' . __('so this GL analysis item could not be added'),'warn');
203	
204		} else {
205			$AllowThisPosting = true;
206	 		if ($_SESSION['ProhibitJournalsToControlAccounts'] == 1) {
207	 			if ($_SESSION['CompanyRecord']['gllink_debtors'] == '1' AND $_POST['GLCode'] == $_SESSION['CompanyRecord']['debtorsact']) {
208	 				prnMsg(__('Payments involving the debtors control account cannot be entered. The general ledger debtors ledger (AR) integration is enabled so control accounts are automatically maintained. This setting can be disabled in System Configuration'), 'warn');
209	 				$AllowThisPosting = false;
210	 			}
211	 			if ($_SESSION['CompanyRecord']['gllink_creditors'] == '1' AND
212					($_POST['GLCode'] == $_SESSION['CompanyRecord']['creditorsact'] OR $_POST['GLCode'] == $_SESSION['CompanyRecord']['grnact'])) {
213	 				prnMsg(__('Payments involving the creditors control account or the GRN suspense account cannot be entered. The general ledger creditors ledger (AP) integration is enabled so control accounts are automatically maintained. This setting can be disabled in System Configuration'), 'warn');
214	 				$AllowThisPosting = false;
215	 			}
216	 			if ($_POST['GLCode'] == $_SESSION['CompanyRecord']['retainedearnings']) {
217	 				prnMsg(__('Payments involving the retained earnings control account cannot be entered. This account is automtically maintained.'), 'warn');
218	 				$AllowThisPosting = false;
219	 			}
220	 		}
221	 		if ($AllowThisPosting) {
222	 			$_SESSION['ReceiptBatch' . $identifier]->add_to_batch(filter_number_format($_POST['Amount']),
223														$_POST['CustomerID'],
224														filter_number_format($_POST['Discount']),
225														$_POST['Narrative'],
226														$_POST['GLCode'],
227														$_POST['PayeeBankDetail'],
228														$_POST['CustomerName'],
229														$_POST['tag']);
230				/*Make sure the same receipt is not double processed by a page refresh */
231				$Cancel = 1;
232			}
233		}
234	}
235	
236	if (isset($Cancel)){
237		unset($_SESSION['CustomerRecord' . $identifier]);
238		unset($_POST['CustomerID']);
239		unset($_POST['CustomerName']);
240		unset($_POST['Amount']);
241		unset($_POST['Discount']);
242		unset($_POST['Narrative']);
243		unset($_POST['PayeeBankDetail']);
244	}
245	
246	
247	if (isset($_POST['CommitBatch'])){
248	
249	 /* once all receipts items entered, process all the data in the
250	  session cookie into the DB creating a single banktrans for the whole amount
251	  of all receipts in the batch and DebtorTrans records for each receipt item
252	  all DebtorTrans will refer to a single banktrans. A GL entry is created for
253	  each GL receipt entry and one for the debtors entry and one for the bank
254	  account debit
255	
