$EarlyDiscountInvoiceID = 0;
if (isset($_GET['Type']) AND $_GET['Type'] == 'Customer' AND $_POST['CustomerID'] != ''
	AND filter_number_format($_POST['Discount']) == 0 AND filter_number_format($_POST['Amount']) > 0) {
	$SQL = "SELECT debtorsmaster.pymtdiscount,
					paymentterms.discountpercent,
					paymentterms.discountdays,
					currencies.decimalplaces
				FROM debtorsmaster
				INNER JOIN paymentterms ON debtorsmaster.paymentterms = paymentterms.termsindicator
				INNER JOIN currencies ON debtorsmaster.currcode = currencies.currabrev
				WHERE debtorsmaster.debtorno = '" . $_POST['CustomerID'] . "'";
	$Result = DB_query($SQL);
	$EarlyRow = DB_fetch_array($Result);
	if ($EarlyRow AND $EarlyRow['pymtdiscount'] == 0
		AND $ReceiptTypes[$_SESSION['ReceiptBatch' . $identifier]->ReceiptType]['percentdiscount'] == 0
		AND $EarlyRow['discountpercent'] > 0 AND $EarlyRow['discountdays'] > 0) {
		$BankedDate = FormatDateForSQL($_SESSION['ReceiptBatch' . $identifier]->DateBanked);
		$AmountPaid = filter_number_format($_POST['Amount']);
		$SQL = "SELECT id, trandate, balance
					FROM debtortrans
					WHERE debtorno = '" . $_POST['CustomerID'] . "'
					AND type = 10
					AND settled = 0
					AND balance > 0
					AND DATE_ADD(trandate, INTERVAL " . (int) $EarlyRow['discountdays'] . " DAY) >= '" . $BankedDate . "'
				ORDER BY trandate, id";
		$Result = DB_query($SQL);
		$AlreadyClaimed = array();
		foreach ($_SESSION['ReceiptBatch' . $identifier]->Items as $BatchItem) {
			if (!empty($BatchItem->AllocateToInvoice)) {
				$AlreadyClaimed[$BatchItem->AllocateToInvoice] = 1;
			}
		}
		while ($InvRow = DB_fetch_array($Result)) {
			if (isset($AlreadyClaimed[$InvRow['id']])) {
				continue;
			}
			$EarlyDiscount = EarlyPaymentDiscountAmount($InvRow['balance'], $EarlyRow['discountpercent'], $EarlyRow['decimalplaces']);
			if ($EarlyDiscount > 0 AND abs($InvRow['balance'] - $EarlyDiscount - $AmountPaid) < CurrencyTolerance($_SESSION['ReceiptBatch' . $identifier]->Currency)) {
				$_POST['Discount'] = $EarlyDiscount;
				$EarlyDiscountInvoiceID = $InvRow['id'];
				break;
			}
		}
	}
}

