if ($ReceiptItem->AllocateToInvoice > 0) {
	/* Early payment discount taken: allocate receipt plus discount to the invoice and settle both */
	$ReceiptTransID = DB_Last_Insert_ID('debtortrans', 'id');
	$AllocAmount = $ReceiptItem->Amount + $ReceiptItem->Discount;
	$SQL = "INSERT INTO custallocns (datealloc, amt, transid_allocfrom, transid_allocto)
			VALUES ('" . FormatDateForSQL($_SESSION['ReceiptBatch' . $identifier]->DateBanked) . "',
				'" . $AllocAmount . "',
				'" . $ReceiptTransID . "',
				'" . $ReceiptItem->AllocateToInvoice . "')";
	$ErrMsg = __('Cannot insert the allocation of the receipt to the invoice because');
	$Result = DB_query($SQL, $ErrMsg, '', true);

	$SQL = "UPDATE debtortrans
			SET alloc = alloc + " . $AllocAmount . ",
			settled = IF(ABS(ovamount + ovgst + ovfreight + ovdiscount - (alloc + " . $AllocAmount . ")) < " . CurrencyTolerance($_SESSION['ReceiptBatch' . $identifier]->Currency) . ", 1, 0)
			WHERE id = '" . $ReceiptItem->AllocateToInvoice . "'";
	$ErrMsg = __('Cannot update the invoice allocation because');
	$Result = DB_query($SQL, $ErrMsg, '', true);

	$SQL = "UPDATE debtortrans
			SET alloc = '" . -$AllocAmount . "',
			settled = 1
			WHERE id = '" . $ReceiptTransID . "'";
	$ErrMsg = __('Cannot update the receipt allocation because');
	$Result = DB_query($SQL, $ErrMsg, '', true);
}

