if (isset($_POST['PrintPDFAndProcess'])) {
	if ($AccumDiscount != 0 AND $_SESSION['CompanyRecord']['gllink_creditors'] == 1) {
		/* Account for the discount taken: debit creditors, credit discount received (functional currency) */
		$DiscountTransNo = GetNextTransNo(22);
		$DiscountPeriodNo = GetPeriod(Date($_SESSION['DefaultDateFormat']));
		$DiscountNarrative = __('Early payment discount taken on payment run') . ' ' . $_POST['Currency'] . ' ' . locale_number_format($AccumDiscount, $CurrDecimalPlaces);
		$DiscountFunctional = $AccumDiscount / filter_number_format($_POST['ExRate']);
		$SQL = "INSERT INTO gltrans (type, typeno, trandate, periodno, account, narrative, amount)
				VALUES (22, '" . $DiscountTransNo . "', '" . date('Y-m-d') . "', '" . $DiscountPeriodNo . "',
					'" . $_SESSION['CompanyRecord']['creditorsact'] . "', '" . $DiscountNarrative . "', '" . $DiscountFunctional . "')";
		$ErrMsg = __('Cannot insert a GL transaction for the creditors account debit because');
		$ProcessResult = DB_query($SQL, $ErrMsg, '', true);
		$SQL = "INSERT INTO gltrans (type, typeno, trandate, periodno, account, narrative, amount)
				VALUES (22, '" . $DiscountTransNo . "', '" . date('Y-m-d') . "', '" . $DiscountPeriodNo . "',
					'" . $_SESSION['CompanyRecord']['pytdiscountact'] . "', '" . $DiscountNarrative . "', '" . -$DiscountFunctional . "')";
		$ErrMsg = __('Cannot insert a GL transaction for the payment discount credit because');
		$ProcessResult = DB_query($SQL, $ErrMsg, '', true);
	}
	DB_Txn_Commit();
}

